// Personal study data stays on this browser. Stable source names survive catalog re-indexing.
export const recordKey=r=>(r.sex||'male')+':'+(r.original||r.name);
export function studyStore(storage){const key='anatomy-study-v1';let data={favorites:[],notes:{},view:null};try{const raw=JSON.parse(storage.getItem(key)||'null');if(raw&&typeof raw==='object'){data.favorites=Array.isArray(raw.favorites)?raw.favorites.filter(x=>typeof x==='string'):[];data.notes=raw.notes&&typeof raw.notes==='object'&&!Array.isArray(raw.notes)?Object.fromEntries(Object.entries(raw.notes).filter(([k,v])=>typeof v==='string')):{};data.view=raw.view||null;}}catch{}
 const save=()=>{storage.setItem(key,JSON.stringify(data));};return{has:r=>data.favorites.includes(recordKey(r)),note:r=>data.notes[recordKey(r)]||'',favorites:records=>records.filter(r=>data.favorites.includes(recordKey(r))),toggle(r){const old=[...data.favorites],k=recordKey(r);data.favorites=data.favorites.includes(k)?data.favorites.filter(x=>x!==k):[...data.favorites,k];try{save();}catch(e){data.favorites=old;throw e;}return data.favorites.includes(k);},setNote(r,value){const k=recordKey(r),old=data.notes[k];if(value.length>4000)throw Error('Not en fazla 4.000 karakter olabilir.');if(value.trim())data.notes[k]=value;else delete data.notes[k];try{save();}catch(e){if(old===undefined)delete data.notes[k];else data.notes[k]=old;throw e;}},saveView(view){const old=data.view;data.view=view;try{save();}catch(e){data.view=old;throw e;}},getView:()=>data.view};}
export function validView(v){return v&&v.version===1&&['male','female'].includes(v.sex)&&Array.isArray(v.layers)&&v.layers.every(x=>typeof x==='string')&&['camera','target'].every(k=>Array.isArray(v[k])&&v[k].length===3&&v[k].every(n=>Number.isFinite(n)&&Math.abs(n)<30))&&Array.isArray(v.hidden)&&v.hidden.every(x=>typeof x==='string')&&typeof v.cut==='object'&&v.cut!==null;}
